function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 100) return 'word needs 1 to 100 characters.';
  if (!/^[a-z]+$/.test(word)) return 'word uses lowercase English letters only.';
  return null;
}

