function countVowelSubstrings(word) {
  const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
  let count = 0;

  for (let start = 0; start < word.length; start++) {
    const seen = new Set();
    for (let end = start; end < word.length; end++) {
      if (!vowels.has(word[end])) break;
      seen.add(word[end]);
      if (seen.size === 5) count++;
    }
  }
  return count;
}

brute:
function countVowelSubstrings(word) {
  let total = 0;
  for (let i = 0; i < word.length; i++) {
    for (let j = i + 1; j <= word.length; j++) {
      const piece = word.slice(i, j);
      if (!/^[aeiou]+$/.test(piece)) continue;
      if ('aeiou'.split('').every(v => piece.includes(v))) total++;
    }
  }
  return total;
}

