function generate(rand, size) {
  const n = size === 'large' ? 100 : 1 + Math.floor(rand() * 16);
  const consonantRate = rand() < 0.3 ? 0 : rand() * 0.2;
  const others = 'bcdfghjklmnpqrstvwxyz';
  let word = '';
  for (let i = 0; i < n; i++) {
    if (rand() < consonantRate) word += others[Math.floor(rand() * others.length)];
    else word += 'aeiou'[Math.floor(rand() * 5)];
  }
  return [word];
}
